      {
        "statement": "The company manufactures metal components for industries including semiconductor, robotics, chemical processing, home furnishings, electronic components, and automotive aftermarket.",
        "label": "fact",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": "Ardent Industries provides top-notch metal fabrication solutions for a wide range of industries, including but not limited to semiconductor, robotics, chemical processing, home furnishings,"
      },
      {
        "statement": "Ardent Industries is a B2B and custom metal manufacturing shop rather than a residential HVAC, plumbing, or electrical home-service contractor.",
        "label": "inference",
        "sourceUrl": "https://ardentindustries.net/",
        "quote": null
      }
    ]
  },
